'use strict';
const DIMENSIONS = [
 {id:'risk',name:'风险预算',advice:'把“最多能亏多少”写在下单之前，再由损失预算反推仓位。'},
 {id:'probability',name:'概率推理',advice:'用概率、收益幅度和成本一起算期望，不只数赢了几次。'},
 {id:'evidence',name:'证据判断',advice:'先定比较基准，保留完整记录，再用独立样本验证策略。'},
 {id:'discipline',name:'决策纪律',advice:'写下入场依据、退出条件和复盘日期，避免让盈亏替代判断。'}
];
const QUESTIONS = [
 {dim:'risk',title:'这一笔，最多能放多大仓位？',scenario:'账户 10 万元，单笔损失上限为账户的 1%。计划在买入价下方 10% 止损。忽略手续费、滑点和跳空，允许的最大买入金额是多少？',options:['20,000 元','10,000 元','5,000 元','100,000 元'],points:[0,3,1,0],why:'损失预算为 1,000 元，最大仓位 = 1,000 ÷ 10% = 10,000 元。实际交易还应为滑点和跳空留余量；止损价不是损失保证。',rubrics:['预计亏损 2,000 元，超过上限。','恰好满足题设的最大仓位。','不超预算，但没有算出最大仓位。','预计亏损 10,000 元，严重超过上限。']},
 {dim:'probability',title:'跌了 40%，要涨多少才能回本？',scenario:'一项投资从 100 元跌到 60 元。忽略费用与分红，从现在的价格回到 100 元，需要上涨多少？',options:['40%','60%','66.7%','100%'],points:[0,1,3,0],why:'损失和恢复不是对称百分比。需要上涨 (100 − 60) ÷ 60 = 66.7%。亏损越大，回本所需涨幅越陡。',rubrics:['把原始本金当成了恢复涨幅的分母。','接近，但不是正确计算结果。','使用当前价格作分母，计算正确。','上涨 100% 会达到 120 元，超过回本水平。']},
 {dim:'evidence',title:'谁的高收益，更值得进一步研究？',scenario:'两组合覆盖相同 5 年，费用口径和分布特征可比。A 年均收益 12%、年波动 10%；B 年均收益 20%、年波动 30%；无风险收益 3%。只比较这里的收益与波动，谁的夏普比率更高？',options:['B，因为收益高 8 个百分点','A，因为超额收益与波动之比更高','两者相同，因为都在盈利','资料足够，但只看波动就选 A'],points:[0,3,0,1],why:'A 的比率为 (12−3)÷10=0.90；B 为 (20−3)÷30≈0.57。在题设下 A 更高，但这不能替代对尾部风险、相关性和可重复性的研究。',rubrics:['收益高不等于每单位波动的超额收益高。','按题设正确比较了风险调整收益。','盈利与否不能判断比率相同。','结论碰巧相同，但忽略了收益和无风险利率。']},
 {dim:'discipline',title:'连续亏损后，下一步怎么走？',scenario:'策略连续亏损 3 次，累计损失仍在预先设定的预算内，尚未触发暂停规则。你也还没有足够证据判断策略失效。最符合既定流程的做法是什么？',options:['下一笔加倍仓位，把损失补回来','立即改用今天涨幅最大的策略','按原风险规则继续，并检查执行与假设','暂停复盘，等赚回来以后再检查'],points:[0,1,3,0],why:'没有触发停止规则时，应遵循预先承诺的风险约束，同时复查执行和假设。需要改变策略时应依据新证据；连续 3 次亏损本身不足以断言失效。',rubrics:['把恢复本金的情绪当成了加仓依据。','可以研究替代策略，但追涨缺乏检验。','保持事先约束，同时主动检验证据。','让短期盈亏决定是否检查过程。']},
 {dim:'risk',title:'五只股票，算五份风险吗？',scenario:'你把股票仓位平均分给 5 家同产业、商业模式相似的公司。你想降低共同的行业下跌风险。最需要补做的检查是什么？',options:['确认每家公司名字不同','检查相关性和共同风险暴露','确认仓位正好各占 20%','确认每家公司近期都上涨'],points:[0,3,1,0],why:'分散名字不一定分散风险。共同产业、估值驱动和收入来源可能令五个仓位同时下跌；需要看相关性与集中暴露。',rubrics:['不同证券名称不是风险独立的证据。','直接针对题设的共同风险进行检查。','等权改善个股集中度，但不能排除行业集中。','同时上涨不证明未来风险已分散。']},
 {dim:'probability',title:'胜率不高，策略就没价值吗？',scenario:'某策略每笔有 40% 概率赚 3%，60% 概率亏 1%。每笔总交易成本固定为 0.2%。假设这些概率可靠，单笔净收益的算术期望是多少？',options:['−0.4%','+0.4%','+0.6%','+1.8%'],points:[0,3,1,0],why:'期望 = 40%×3% − 60%×1% − 0.2% = +0.4%。胜率不等于优势；正的算术期望也不保证适当仓位、复利增长或小样本盈利。',rubrics:['把胜率低于一半等同于负期望。','同时纳入收益幅度、概率和费用。','算对毛期望，但遗漏了交易成本。','没有正确加权两种结果与成本。']},
 {dim:'evidence',title:'200 次回测里，最漂亮的那个。',scenario:'你尝试了 200 组参数，挑出历史夏普最高的一组。想判断它是否有可重复的优势，哪一步提供的新增证据最有力？',options:['再看一遍这组参数的原样回测','用未参与选参的数据检验，并记录全部尝试','删掉亏损年份，把规律看得更清楚','与同一数据里的另外 199 组比较'],points:[1,3,0,1],why:'反复筛选容易把噪声选成“规律”。独立的留出数据或前瞻记录能提供新增证据；仍需考虑多重试验、费用与样本独立性。',rubrics:['可以检查错误，但不是独立的性能证据。','增加独立验证，并保留筛选规模的信息。','按结果删数据会扩大偏差。','描述了筛选结果，仍然复用了选参样本。']},
 {dim:'discipline',title:'赚钱的一笔，也可能是坏决策。',scenario:'某人借钱满仓一个未经研究的资产，意外赚了 50%；另一个人遵守事先记录的分散与风险规则，这个月却亏了 2%。仅凭这两次结果，怎样复盘更合理？',options:['前者决策一定更好，因为赚得多','后者一定更强，因为风险较低','暂不能判定，分别检查决策依据与长期表现','双方决策都正确，因为结果已发生'],points:[0,1,3,0],why:'结果会受运气影响。判断过程要看当时可用的信息与约束；判断持续能力要看更长、更完整的记录。一次输赢不能给两人排位。',rubrics:['以一次事后结果替代当时的决策质量。','较守规则是过程信息，但不能据此证明更强。','区分了过程、运气与持续表现的证据。','事实发生不意味着决策合理。']},
 {dim:'risk',title:'一年后必须使用的钱。',scenario:'你一年后要支付一笔确定的费用，没有其他资金可补缺口，也不能接受本金明显亏损。对这笔专用资金，最符合约束的安排是什么？',options:['投入波动很大的资产，争取多赚一点','匹配期限、币种与流动性，优先保障支付','投向三个同类高波动资产，降低风险','全部锁定五年，换取更高利率'],points:[0,3,1,0],why:'投资目标包括现金流约束。对无法承受缺口的一年期支出，应优先匹配到期时间、币种与流动性，并检查信用风险，而非只追求收益。',rubrics:['价格风险可能导致必须支付时资金不足。','直接满足题设的付款期限和本金约束。','分散部分个别风险，仍可能产生支付缺口。','期限错配，届时资金不可用。']},
 {dim:'probability',title:'一个“80% 准”的信号。',scenario:'100 次情况中有 20 次真实上涨。信号能识别其中 80%；在其余未上涨的情况中，有 20% 也会误报上涨。收到上涨信号时，真实上涨的概率是多少？',options:['80%','20%','50%','64%'],points:[0,1,3,1],why:'真实上涨且报信号的情况为 20×80%=16 次；未上涨却报信号为 80×20%=16 次。条件概率为 16÷(16+16)=50%。需要同时看基准概率与误报。',rubrics:['混淆了识别率和收到信号后的上涨概率。','只用了原始上涨比例，没有更新证据。','正确结合基准概率、识别率与误报率。','组合了部分概率，但没有计算条件概率。']},
 {dim:'evidence',title:'赚了 20%，说明跑赢了吗？',scenario:'同一年度、同一币种，你的组合扣费含分红收益为 20%，事先选定的可比基准收益为 30%。仅从这些数据可直接得出什么？',options:['已获得 20% 的投资优势','收益差为 −10 个百分点，风险调整优势仍未知','收益差为 +10 个百分点','一定完全没有投资能力'],points:[0,3,0,1],why:'组合相对基准少赚了 10 个百分点。但没有风险暴露、波动与更长记录，不能直接断言 alpha 为负或个人没有能力。',rubrics:['把绝对收益直接当成可持续优势。','正确计算收益差，并保留风险调整的不确定性。','方向计算错误。','注意到落后，但把一年表现泛化成能力结论。']},
 {dim:'discipline',title:'理由变了，价格还没回本。',scenario:'你买入前记录的核心假设被可靠的新证据推翻，且没有新的持有理由。你最初约定：假设失效就重新评估退出。现在亏损 15%，该如何决策？',options:['等回到买入价再评估，避免实现亏损','加倍买入，降低平均成本','按新信息比较退出与持有，不以买入价作锚','忽略新证据，维持最初的乐观判断'],points:[0,1,3,0],why:'原买入价是历史信息，不是资产未来收益的保证。假设失效时应比较当前可选行动，考虑费用和约束，并执行既定评估流程。',rubrics:['用回本价替代了当前信息下的行动比较。','成本降低不恢复原假设，缺乏新的持有依据。','响应新证据并遵循事先的假设失效规则。','拒绝更新证据，会使原规则失去作用。']}
];
function escapeHTML(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function mean(a){return a.reduce((s,v)=>s+v,0)/a.length;}
function variance(a){if(a.length<2)return 0;const m=mean(a);return a.reduce((s,v)=>s+(v-m)**2,0)/(a.length-1);}
function quizResult(answers){
 if(!Array.isArray(answers)||answers.length!==QUESTIONS.length||answers.some(a=>!a||!Number.isInteger(a.choice)||a.choice<0||a.choice>3||!Number.isFinite(a.confidence)||a.confidence<25||a.confidence>100))throw new Error('需要 12 道有效答案与 25–100% 的信心值。');
 const total=answers.reduce((s,a,i)=>s+QUESTIONS[i].points[a.choice],0);
 const dimensions=DIMENSIONS.map(d=>{const ids=QUESTIONS.map((q,i)=>q.dim===d.id?i:-1).filter(i=>i>=0);return {...d,score:Math.round(ids.reduce((s,i)=>s+QUESTIONS[i].points[answers[i].choice],0)/(ids.length*3)*100)};});
 const correct=answers.reduce((s,a,i)=>s+(QUESTIONS[i].points[a.choice]===3?1:0),0);const avgConfidence=mean(answers.map(a=>a.confidence));
 return {score:Math.round(total/36*100),total,correct,accuracy:correct/12*100,averageConfidence:avgConfidence,confidenceGap:avgConfidence-correct/12*100,dimensions};
}
function parseReturns(text){
 if(typeof text!=='string'||!text.trim())throw new Error('请先输入月度收益，或填入演示数据。');
 if(text.length>150000)throw new Error('记录过长，请控制在 1,200 个月以内。');
 const lines=text.trim().split(/\r?\n/).map(l=>l.trim()).filter(Boolean);const rows=[];
 for(let i=0;i<lines.length;i++){
  const line=lines[i].replace(/，/g,',').replace(/％/g,'%');
  if(i===0&&/^(月份|month|date)\s*[,\t;]/i.test(line))continue;
  const parts=line.split(/[,;\t]/).map(p=>p.trim());
  if(parts.length!==3)throw new Error(`第 ${i+1} 行应包含月份、组合收益、基准收益三个值。`);
  const m=/^(\d{4})-(0[1-9]|1[0-2])$/.exec(parts[0]);if(!m||Number(m[1])<1900||Number(m[1])>2100)throw new Error(`第 ${i+1} 行的月份请使用 YYYY-MM，例如 2024-01。`);
  const vals=parts.slice(1).map(p=>{if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)\s*%?$/.test(p))throw new Error(`第 ${i+1} 行的收益必须是数字，单位为百分比。`);return Number(p.replace(/\s*%$/,''))/100;});
  if(vals.some(v=>!Number.isFinite(v)||v< -1||v>10))throw new Error(`第 ${i+1} 行的月收益需在 −100% 到 1,000% 之间。`);
  const monthIndex=Number(m[1])*12+Number(m[2])-1;
  if(rows.length&&monthIndex!==rows[rows.length-1].monthIndex+1)throw new Error(`第 ${i+1} 行月份不连续或重复；请按时间升序补齐每个月。`);
  if(rows.length&&((rows[rows.length-1].portfolio===-1)||(rows[rows.length-1].benchmark===-1)))throw new Error('出现 −100% 终止损失后不能继续计算该组合的后续百分比收益。');
  rows.push({month:parts[0],monthIndex,portfolio:vals[0],benchmark:vals[1]});
 }
 if(rows.length<3)throw new Error('至少需要 3 个连续月份的数据。');if(rows.length>1200)throw new Error('最多支持 1,200 个月。');return rows;
}
function navPath(returns){let value=1,peak=1,drawdown=0;const values=[1];for(const r of returns){value*=1+r;if(!Number.isFinite(value))throw new Error('累计净值过大，无法可靠计算，请检查收益单位。');values.push(value);peak=Math.max(peak,value);drawdown=Math.max(drawdown,1-value/peak);}return {values,end:value,drawdown};}
function hacMeanInterval(active){const n=active.length,m=mean(active),e=active.map(x=>x-m),lag=Math.min(Math.floor(4*(n/100)**(2/9)),Math.floor(n/4));let longVar=e.reduce((s,x)=>s+x*x,0)/n;for(let k=1;k<=lag;k++){let covariance=0;for(let t=k;t<n;t++)covariance+=e[t]*e[t-k];longVar+=2*(1-k/(lag+1))*covariance/n;}const se=Math.sqrt(Math.max(0,longVar)/n);return {low:(m-1.96*se)*12,high:(m+1.96*se)*12,mean:m*12,lag};}
function analyzeReturns(rows,rfAnnual){
 if(!Array.isArray(rows)||rows.length<3||rows.some(r=>!Number.isFinite(r.portfolio)||!Number.isFinite(r.benchmark)||r.portfolio< -1||r.benchmark< -1||r.portfolio>10||r.benchmark>10))throw new Error('需要有效且连续的月收益记录。');
 if(!Number.isFinite(rfAnnual)||rfAnnual< -.1||rfAnnual>.3)throw new Error('年无风险收益率需在 −10% 到 30% 之间。');
 const p=rows.map(r=>r.portfolio),b=rows.map(r=>r.benchmark),active=p.map((v,i)=>v-b[i]),pn=navPath(p),bn=navPath(b),n=rows.length,rfMonth=(1+rfAnnual)**(1/12)-1;
 const ps=Math.sqrt(variance(p)),as=Math.sqrt(variance(active));const annualized=n>=12;
 const cagr=annualized?pn.end**(12/n)-1:null,bcagr=annualized?bn.end**(12/n)-1:null;
 const result={n,portfolio:pn,benchmark:bn,cumulative:pn.end-1,benchmarkCumulative:bn.end-1,cagr,benchmarkCagr:bcagr,cagrGap:annualized?cagr-bcagr:null,volatility:annualized?ps*Math.sqrt(12):null,sharpe:annualized&&ps>1e-12?(mean(p)-rfMonth)/ps*Math.sqrt(12):null,informationRatio:annualized&&as>1e-12?mean(active)/as*Math.sqrt(12):null,averageActiveAnnual:annualized?mean(active)*12:null,interval:n>=36?hacMeanInterval(active):null,start:rows[0].month,end:rows[n-1].month};
 const check=[result.cumulative,result.benchmarkCumulative,result.cagr,result.benchmarkCagr,result.volatility,result.sharpe,result.informationRatio];if(check.some(x=>x!==null&&!Number.isFinite(x)))throw new Error('结果超出可可靠计算的范围，请检查数据。');return result;
}
const SAMPLE_BENCHMARK=[2.8,-1.9,3.6,1.4,-2.7,4.1,2.2,-3.1,-4.4,3.5,5.2,2.1,-1.6,3.2,2.4,-3.8,1.5,3.7,1.6,-2.9,2.5,-1.2,3.8,1.7,2.2,-3.4,1.8,-2.1,4.0,2.6,-1.7,2.9,1.2,-2.3,3.3,2.4];
const SAMPLE_EDGES=[.5,.2,-.2,.6,.4,-.3,.5,-.1,.8,-.4,.4,.3,.3,-.2,.5,-.3,.6,.2,-.2,.4,.5,-.4,.3,.2,-.1,.7,.3,.5,-.3,.4,.2,-.2,.6,.3,-.1,.4];
const SAMPLE='月份,组合收益%,基准收益%\n'+SAMPLE_BENCHMARK.map((b,i)=>`${2023+Math.floor(i/12)}-${String(i%12+1).padStart(2,'0')},${(b+SAMPLE_EDGES[i]).toFixed(1)},${b.toFixed(1)}`).join('\n');
const InvestmentRuler={QUESTIONS,DIMENSIONS,quizResult,parseReturns,analyzeReturns,SAMPLE};
if(typeof window!=='undefined')window.InvestmentRuler=InvestmentRuler;
if(typeof module!=='undefined'&&module.exports)module.exports=InvestmentRuler;
if(typeof document!=='undefined'){
 const $=id=>document.getElementById(id);const state={current:0,draft:null,confidence:70,answers:Array(12).fill(null),view:'question',performance:null};
 const pageTitles={assessment:'决策测评',performance:'实盘分析',method:'评分方法'};
 function switchPage(name){if(!pageTitles[name])return;document.querySelectorAll('.page').forEach(p=>{p.hidden=p.id!==name;p.classList.toggle('active',p.id===name);});document.querySelectorAll('[data-page]').forEach(b=>{const on=b.dataset.page===name;b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('page-label').textContent=pageTitles[name];if(location.hash!==`#${name}`)history.replaceState(null,'',`#${name}`);}
 document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>switchPage(b.dataset.page)));
 document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>switchPage(b.dataset.go)));
 function updateProfile(){const answered=state.answers.filter(Boolean).length;const complete=answered===12;
  $('answered-count').textContent=`已完成 ${answered} 题`;$('progress-fill').style.width=`${answered/12*100}%`;$('quiz-progress').setAttribute('aria-valuenow',String(answered));$('profile-status').textContent=complete?'测评完成':answered?'测评中':'待测评';
  const result=complete?quizResult(state.answers):null;$('score-number').textContent=complete?String(result.score):'—';$('score-dial').style.background=`conic-gradient(var(--lime) ${complete?result.score*3.6:0}deg,#edf0f4 0deg)`;
  $('score-description').textContent=complete?(result.score>=85?'本次情境掌握较好。继续用独立实盘记录验证。':result.score>=65?'已有基础。优先复盘得分较低的能力。':'关键规则仍有遗漏。从最低分能力开始练习。'):'完成测评后，获得你的分数与复盘。';
  $('dimension-bars').innerHTML=DIMENSIONS.map(d=>{const ids=QUESTIONS.map((q,i)=>q.dim===d.id?i:-1).filter(i=>i>=0),done=ids.filter(i=>state.answers[i]);const full=done.length===3,score=full?Math.round(done.reduce((s,i)=>s+QUESTIONS[i].points[state.answers[i].choice],0)/9*100):null;return `<div class="dimension-row"><div><span>${d.name}</span><strong>${full?score+' / 100':done.length+'/3 题'}</strong></div><div class="dimension-track"><span style="width:${full?score:0}%"></span></div></div>`;}).join('');
 }
 function renderQuestion(){state.view='question';const i=state.current,q=QUESTIONS[i],answer=state.answers[i];const selected=answer?answer.choice:state.draft;const dim=DIMENSIONS.find(d=>d.id===q.dim);$('question-count').textContent=`情境 ${String(i+1).padStart(2,'0')} / 12`;
  $('question-card').innerHTML=`<div class="question-top"><span class="dimension-tag">${dim.name}</span><span class="question-number">SCENARIO ${String(i+1).padStart(2,'0')}</span></div><h2 class="question-title">${q.title}</h2><p class="scenario">${q.scenario}</p><div class="options" role="group" aria-label="选择你的决策">${q.options.map((o,k)=>`<button class="option-button ${selected===k?'selected':''} ${answer&&q.points[k]===3?'best':''}" data-option="${k}" aria-pressed="${selected===k}" ${answer?'disabled':''}><span class="option-letter">${'ABCD'[k]}</span><span>${o}</span>${answer?`<span class="option-points">${q.points[k]} / 3</span>`:''}</button>`).join('')}</div>${answer?`<div class="feedback ${q.points[answer.choice]===3?'':'needs-review'}" aria-live="polite"><div class="feedback-heading"><span>${q.points[answer.choice]===3?'这一选择，满足题设目标':'这一步，值得再复盘'}</span><span class="feedback-score">${q.points[answer.choice]} / 3 分</span></div><p>${q.why}</p><details><summary>查看全部选项的评分理由</summary><div class="rubric-list">${q.rubrics.map((r,k)=>`<div><b>${'ABCD'[k]} · ${q.points[k]} 分</b> ${r}</div>`).join('')}</div></details></div>`:`<div class="confidence-block"><label for="confidence" class="confidence-label"><span>你有多确定，这是最佳选择？</span><strong id="confidence-value">${state.confidence}%</strong></label><input type="range" id="confidence" min="25" max="100" step="5" value="${state.confidence}"><div class="confidence-endpoints"><span>25% · 猜测</span><span>100% · 完全确定</span></div></div>`}<div class="question-actions"><button class="subtle-button" id="previous-question" ${i===0?'disabled':''}>上一题</button><button class="primary-button" id="submit-question" ${!answer&&selected===null?'disabled':''}>${answer?(i===11?'查看评估报告':'下一题'):'确认并复盘'}</button></div>`;
  document.querySelectorAll('[data-option]').forEach(b=>b.addEventListener('click',()=>{state.draft=Number(b.dataset.option);renderQuestion();}));
  if(!answer)$('confidence').addEventListener('input',e=>{state.confidence=Number(e.target.value);$('confidence-value').textContent=`${state.confidence}%`;});
  $('previous-question').addEventListener('click',()=>{if(state.current>0){state.current--;state.draft=null;renderQuestion();}});
  $('submit-question').addEventListener('click',()=>{if(!answer){if(state.draft===null)return;state.answers[i]={choice:state.draft,confidence:state.confidence};renderQuestion();updateProfile();}else if(i===11){if(state.answers.every(Boolean))renderReport();else{state.current=state.answers.findIndex(a=>!a);state.draft=null;renderQuestion();}}else{state.current++;state.draft=null;state.confidence=70;renderQuestion();}});
 }
 function renderReport(){state.view='report';const r=quizResult(state.answers),weak=[...r.dimensions].sort((a,b)=>a.score-b.score).slice(0,2);$('question-count').textContent='评估报告 / 12 题已完成';
  const gap=`${r.confidenceGap>=0?'+':''}${r.confidenceGap.toFixed(1)} 个百分点`;
  $('question-card').innerHTML=`<div class="completed-header"><span class="completed-label">测评完成</span><h2>${r.score>=85?'你有一套相当清楚的决策框架。':r.score>=65?'你已经有基础，也找到了盲点。':'先把关键规则变成习惯。'}</h2><p>总得分 ${r.total} / 36；最佳答案命中 ${r.correct} / 12。分数仅描述本次题目，不是未来盈利的概率。</p></div><div class="calibration-box"><div><span>本次信心偏差</span><strong>${gap}</strong></div><p>平均信心 ${r.averageConfidence.toFixed(1)}%，最佳答案命中率 ${r.accuracy.toFixed(1)}%。${r.confidenceGap>10?'这次信心高于命中率，复盘时尤其检查“很确定却答错”的题。':r.confidenceGap< -10?'这次信心低于命中率，部分判断可能比你想的更可靠。':'本次平均信心与命中率比较接近。'} 样本只有 12 题。</p></div><h3 class="next-step-title">从这两件事开始</h3>${weak.map((d,i)=>`<div class="next-step"><span>0${i+1}</span><div><strong>${d.name} · ${d.score} 分</strong><p>${d.advice}</p></div></div>`).join('')}<div class="report-actions"><button class="primary-button" id="go-performance">用实盘记录继续验证</button><button class="subtle-button" id="review-answers">逐题复盘</button><button class="text-button" id="restart-quiz">重新测评</button></div>`;
  $('go-performance').addEventListener('click',()=>switchPage('performance'));$('review-answers').addEventListener('click',renderReview);$('restart-quiz').addEventListener('click',restartQuiz);updateProfile();
 }
 function restartQuiz(){state.answers=Array(12).fill(null);state.current=0;state.draft=null;state.confidence=70;renderQuestion();updateProfile();}
 function renderReview(){state.view='review';$('question-card').innerHTML=`<div class="review-heading"><h2>逐题复盘</h2><button class="subtle-button" id="back-report">返回报告</button></div>${QUESTIONS.map((q,i)=>{const a=state.answers[i],best=q.points.indexOf(3);return `<details class="review-item"><summary>${String(i+1).padStart(2,'0')} · ${q.title}<span class="review-points">${q.points[a.choice]} / 3</span></summary><p>${q.scenario}</p><p>你的选择：${'ABCD'[a.choice]} · ${q.options[a.choice]}；信心 ${a.confidence}%。<br>题设最佳：${'ABCD'[best]} · ${q.options[best]}。</p><p>${q.why}</p><div class="rubric-list">${q.rubrics.map((r,k)=>`<div>${'ABCD'[k]} · ${q.points[k]} 分：${r}</div>`).join('')}</div></details>`;}).join('')}`;$('back-report').addEventListener('click',renderReport);}
 function formatPct(v,d=1){if(v===null)return'需 ≥12 月';return `${v>0?'+':''}${(v*100).toFixed(d)}%`;}
 function formatPp(v){return v===null?'需 ≥12 月':`${v>0?'+':''}${(v*100).toFixed(1)} 个百分点`;}
 function buildChart(r,rows,name){const all=[...r.portfolio.values,...r.benchmark.values],max=Math.max(...all),min=Math.min(...all);const padding=(max-min)*.14||.1,lo=Math.max(0,min-padding),hi=max+padding;const w=520,h=214,left=49,right=15,top=17,bottom=29;const x=i=>left+i/r.n*(w-left-right),y=v=>top+(hi-v)/(hi-lo)*(h-top-bottom);const line=a=>a.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' ');let grid='';for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;grid+=`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end">${v.toFixed(2)}</text>`;}
  return `<div class="chart-card"><div class="chart-heading"><h2>月末净值 · 起始值 1</h2><div class="chart-legend"><span>你的组合</span><span>${escapeHTML(name)}</span></div></div><svg class="chart-svg" role="img" aria-label="组合与基准的月末净值曲线，从 ${r.start} 到 ${r.end}；详细累计收益见上方指标" viewBox="0 0 ${w} ${h}">${grid}<path class="benchmark-line" d="${line(r.benchmark.values)}"/><path class="portfolio-line" d="${line(r.portfolio.values)}"/><text x="${left}" y="${h-5}">起点</text><text x="${x(Math.round(r.n/2))}" y="${h-5}" text-anchor="middle">${rows[Math.max(0,Math.round(r.n/2)-1)].month}</text><text x="${w-right}" y="${h-5}" text-anchor="end">${r.end}</text></svg></div>`;
 }
 function renderPerformance(r,rows,isSample){const name=$('benchmark-name').value.trim()||'自选基准';const annual=r.n>=12;const metric=(label,value,detail,cls='')=>`<div class="metric-card"><div class="metric-label">${label}</div><div class="metric-value ${cls}">${value}</div><div class="metric-detail">${escapeHTML(detail)}</div></div>`;const isDefined=r.sharpe!==null,irDefined=r.informationRatio!==null;
  $('performance-results').innerHTML=`<div class="result-topline"><span class="record-length">${r.start} — ${r.end} · ${r.n} 个月</span><span class="sample-label">${isSample?'虚构演示数据':'自填记录 · 未核验'}</span></div><div class="metrics-grid">${metric('累计收益',formatPct(r.cumulative),`基准 ${formatPct(r.benchmarkCumulative)}`,r.cumulative>=0?'positive':'negative')}${metric('月末最大回撤',`−${(r.portfolio.drawdown*100).toFixed(1)}%`,`基准 −${(r.benchmark.drawdown*100).toFixed(1)}%`)}${metric('年化复利收益',formatPct(r.cagr),annual?`基准 ${formatPct(r.benchmarkCagr)}`:'未满一年，不显示年化')}${metric('年化收益差',formatPp(r.cagrGap),'组合年化 − 基准年化',r.cagrGap!==null?(r.cagrGap>=0?'positive':'negative'):'')}${metric('夏普比率',annual?(isDefined?r.sharpe.toFixed(2):'无法计算'):'需 ≥12 月',isDefined?'超额收益 / 波动，常规年化':annual?'收益波动为零，比率不定义':'记录过短')}${metric('年化波动率',r.volatility!==null?`${(r.volatility*100).toFixed(1)}%`:'需 ≥12 月','月收益样本波动 × √12')}${metric('信息比率',annual?(irDefined?r.informationRatio.toFixed(2):'无法计算'):'需 ≥12 月',irDefined?'主动收益 / 跟踪误差，常规年化':annual?'主动收益无波动，比率不定义':'记录过短')}${metric('平均主动收益',formatPct(r.averageActiveAnnual),'月均（组合 − 基准）×12，算术年化')}</div>${buildChart(r,rows,name)}<div class="confidence-card"><h3>${r.n>=36?'记录更长，仍需独立验证':r.n>=12?'初步表现，证据仍有限':'记录偏短，暂不年化'}</h3>${r.interval?`<p>平均主动收益的近似 95% 区间</p><div class="confidence-value">${formatPct(r.interval.low)} 至 ${formatPct(r.interval.high)}</div><p>${r.interval.low<=0&&r.interval.high>=0?'区间跨过零，样本不能清楚区分平均主动收益的正负。':r.interval.low>0?'样本区间在零以上，但风险暴露和样本筛选仍可能解释收益。':'样本区间在零以下；复盘基准是否匹配，再评估成本与策略。'} 这是收益均值区间，不是个人能力的概率。</p>`:`<p>${r.n<12?'至少记录一年后，再查看年化风险收益指标。':'完整保存更多月份，跨市场环境检验。达到 36 个月后才显示本站的均值区间估计。'}</p>`}</div><div class="plain-note"><strong>表现已计算，能力尚不能定论</strong><p>月末数据可能遗漏月内回撤；主动收益未剔除风险因子。基准应事先选定，出入金应从收益中剔除。${isSample?'此处是虚构演示，请换成真实完整记录。':''}</p><button class="text-button" id="performance-method">查看指标公式与局限</button></div>`;
  $('performance-method').addEventListener('click',()=>switchPage('method'));
 }
 function calculatePerformance(){const raw=$('return-data').value;const rfRaw=$('risk-free').value;try{if(!rfRaw.trim())throw new Error('请输入年无风险收益率。');const rows=parseReturns(raw);const r=analyzeReturns(rows,Number(rfRaw)/100);state.performance=r;$('data-error').hidden=true;renderPerformance(r,rows,raw.trim()===SAMPLE.trim());return {status:'calculated',sample:raw.trim()===SAMPLE.trim(),months:r.n,cumulativeReturn:r.cumulative,annualizedReturn:r.cagr,monthlyMaxDrawdown:r.portfolio.drawdown,sharpe:r.sharpe,informationRatio:r.informationRatio,meanActiveInterval:r.interval};}catch(e){$('data-error').hidden=false;$('data-error').textContent=e.message;state.performance=null;$('performance-results').innerHTML='<div class="empty-results"><h2>请先修正输入</h2><p>修正左侧提示后重新计算，<br>旧结果已清除，避免误读。</p></div>';throw e;}}
 function loadExample(){ $('return-data').value=SAMPLE;$('benchmark-name').value='演示基准';$('risk-free').value='2';calculatePerformance();}
 $('calculate-performance').addEventListener('click',()=>{try{calculatePerformance();}catch(_){}});$('load-example').addEventListener('click',loadExample);$('empty-example').addEventListener('click',loadExample);
 $('clear-performance').addEventListener('click',()=>{$('return-data').value='';$('data-error').hidden=true;state.performance=null;$('performance-results').innerHTML='<div class="empty-results"><h2>记录已清空</h2><p>输入新的月度收益，再开始比较。</p></div>';});
 // Hide stale calculated results as soon as an input changes.
 for(const id of ['return-data','risk-free','benchmark-name'])$(id).addEventListener('input',()=>{if(state.performance){state.performance=null;$('performance-results').innerHTML='<div class="empty-results"><h2>输入已更新</h2><p>点击“计算实盘表现”查看新结果。</p></div>';}$('data-error').hidden=true;});
 renderQuestion();updateProfile();switchPage(pageTitles[location.hash.slice(1)]?location.hash.slice(1):'assessment');window.addEventListener('hashchange',()=>switchPage(location.hash.slice(1)));
 // Structured access uses exactly the same state and actions as the visible page.
 const modelContext=document.modelContext;
 if(modelContext&&typeof modelContext.registerTool==='function'){
  const lifecycle=new AbortController();
  const register=t=>{try{Promise.resolve(modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch(_){}};
  register({name:'read_investment_assessment',title:'读取投资评估',description:'读取当前页面的测评完成状态、已完成的决策分和最近计算的实盘指标；不修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('输入必须为空对象。');return {answered:state.answers.filter(Boolean).length,decision:state.answers.every(Boolean)?quizResult(state.answers):null,performance:state.performance?{months:state.performance.n,cumulativeReturn:state.performance.cumulative,annualizedReturn:state.performance.cagr,monthlyMaxDrawdown:state.performance.portfolio.drawdown,sharpe:state.performance.sharpe}:null};}});
  register({name:'calculate_investment_performance',title:'计算投资实盘表现',description:'用给定的连续月收益替换页面输入并立即计算实盘指标，同时打开实盘分析。不会保存或发送记录。收益单位为百分比。',inputSchema:{type:'object',properties:{monthlyReturns:{type:'string',description:'每行 YYYY-MM,组合收益%,基准收益%；至少3个月'},annualRiskFreePercent:{type:'number',minimum:-10,maximum:30},benchmarkName:{type:'string',maxLength:40}},required:['monthlyReturns','annualRiskFreePercent','benchmarkName'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['monthlyReturns','annualRiskFreePercent','benchmarkName'].includes(k))||typeof input.monthlyReturns!=='string'||!Number.isFinite(input.annualRiskFreePercent)||typeof input.benchmarkName!=='string'||input.benchmarkName.length>40)throw new Error('请提供有效的收益文本、无风险年收益率与基准名称。');const rows=parseReturns(input.monthlyReturns);analyzeReturns(rows,input.annualRiskFreePercent/100);$('return-data').value=input.monthlyReturns;$('risk-free').value=String(input.annualRiskFreePercent);$('benchmark-name').value=input.benchmarkName;const result=calculatePerformance();switchPage('performance');return result;}});
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 }
}
